def dec(xi,c,dv,b,LO=0,HI=9):
    x=torch.as_tensor(xi).float().clone(); c=torch.as_tensor(c).float()
    D=torch.tensor(dv,dtype=torch.float32)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,('blocks.0.act',),count=False)
        if LO<=k<HI:
